"""ORD_LINE renumbering for the migrated CRM platform."""


def _order_id(row: dict) -> str:
    """Return ORD_ID using the specified empty-string default."""
    return str(row.get("ORD_ID", ""))


def _line_number(row: dict) -> int:
    """Return LINE_NO as a numeric sorting value."""
    value = row.get("LINE_NO", "")
    if value == "":
        return 0
    return int(value)


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted rows and assign contiguous line numbers per order."""
    surviving = [row for row in lines if row.get("DEL_FLG", "") != "Y"]
    surviving.sort(key=lambda row: (_order_id(row), _line_number(row)))

    result: list[dict] = []
    current_order: str | None = None
    new_line_number = 0

    for row in surviving:
        order_id = _order_id(row)
        if order_id != current_order:
            current_order = order_id
            new_line_number = 1
        else:
            new_line_number += 1

        new_row = dict(row)
        new_row["LINE_NO"] = new_line_number
        result.append(new_row)

    return result
